static real poly(const real *cof, const int n, const real x) {
    real ans = cof[n];
    for (int i=n-1;i>=0;i--) ans = ans*x+cof[i];
    return ans;
}


real besselJ0(const real x) {
    real nump_b, denp_b, numq_b, denq_b, y_b, z_b, ax_b, xx_b;
    if ((ax_b = mw_abs(x)) < 8.0) { //Direct rational function fit.
        const int n = 6;
        y_b = x * x;
        z_b = 64.0 - y_b;
        nump_b = j0r[n];
        denp_b = j0s[n];
        for (int i = n - 1; i >= 0; i--) {
            nump_b = nump_b * z_b + j0r[i];
            denp_b = denp_b * y_b + j0s[i];
        }
        return nump_b * (y_b - xj00) * (y_b - xj10) / denp_b;
    }
    else { //Fitting function(6.5.9).
        const real fac = 1.;
        z_b = 8.0 / ax_b;
        y_b = z_b * z_b;
        xx_b = ax_b - fac * pio4;
        nump_b = j0pn[4];
        denp_b = j0pd[4];
        numq_b = j0qn[4];
        denq_b = j0qd[4];
        for (int i = 3; i >= 0; i--) {
            nump_b = nump_b * y_b + j0pn[i];
            denp_b = denp_b * y_b + j0pd[i];
            numq_b = numq_b * y_b + j0qn[i];
            denq_b = denq_b * y_b + j0qd[i];
        }
        return sqrt(twoopi / ax_b) * (cos(xx_b) * nump_b / denp_b - z_b * sin(xx_b) * numq_b / denq_b);
    }
}

real besselJ1(const real x) { //Returns the Bessel function J1.x/ for any real x
    real nump_b, denp_b, numq_b, denq_b, y_b, z_b, ax_b, xx_b;
    if ((ax_b = mw_abs(x)) < 8.0) { //Direct rational approximation.
        const int n = 6;
        y_b = x * x;
        z_b = 64.0 - y_b;
        nump_b = j1r[n];
        denp_b = j1s[n];
        for (int i = n - 1; i >= 0; i--) {
            nump_b = nump_b * z_b + j1r[i];
            denp_b = denp_b * y_b + j1s[i];
        }
        return x * nump_b * (y_b - xj01) * (y_b - xj11) / denp_b;
    }
    else { //Fitting function(6.5.9).
        const real fac = 3.;
        z_b = 8.0 / ax_b;
        y_b = z_b * z_b;
        xx_b = ax_b - fac * pio4;
        nump_b = j1pn[4];
        denp_b = j1pd[4];
        numq_b = j1qn[4];
        denq_b = j1qd[4];
        for (int i = 3; i >= 0; i--) {
            nump_b = nump_b * y_b + j1pn[i];
            denp_b = denp_b * y_b + j1pd[i];
            numq_b = numq_b * y_b + j1qn[i];
            denq_b = denq_b * y_b + j1qd[i];
        }
        real ans = sqrt(twoopi / ax_b) * (cos(xx_b) * nump_b / denp_b - z_b * sin(xx_b) * numq_b / denq_b);
        return x > 0.0 ? ans : -ans;
    }
}

real besselJ2(const real x) {
    //mw_printf("besselJ2 = 2 * besselJ1(x) / x - besselJ0(x) = 2 * %.6f / %.6f - %.6f = %.6f\n", besselJ1(x), x, besselJ0(x), 2.0 * besselJ1(x) / x - besselJ0(x));
    return 2.0 * besselJ1(x) / x - besselJ0(x);
}

real besselI0(const real x) {
    real ax = mw_abs(x);
    if (ax < 15.0) {
        real y = x*x;
        return poly(i0p,13,y)/poly(i0q,4,225.-y);
    } else {
        real z=1.0-15.0/ax;
        return mw_exp(ax)*poly(i0pp,4,z)/(poly(i0qq,5,z)*mw_sqrt(ax));
    }
}

real besselI1(const real x) {
    real ax = mw_abs(x);
    if (ax < 15.0) {
        real y=x*x;
        return x*poly(i1p,13,y)/poly(i1q,4,225.-y);
     } else {
        real z=1.0-15.0/ax;
        real ans = mw_exp(ax)*poly(i1pp,4,z)/(poly(i1qq,5,z)*mw_sqrt(ax));
        return ans;
    }
}

real besselK0(const real x) {
    if (x <= 1.0) {
        real z=x*x;
        real term = poly(k0pi,4,z)*mw_log(x)/poly(k0qi,2,1.-z);
        return poly(k0p,4,z)/poly(k0q,2,1.-z)-term;
    } else {
        real z=1.0/x;
        return mw_exp(-x)*poly(k0pp,7,z)/(poly(k0qq,7,z)*mw_sqrt(x));
    }
}

real besselK1(const real x) {
    if (x <= 1.0) {
        real z=x*x;
        real term = poly(k1pi,4,z)*mw_log(x)/poly(k1qi,2,1.-z);
        return x*(poly(k1p,4,z)/poly(k1q,2,1.-z)+term)+1./x;
    } else {
        real z=1.0/x;
        return mw_exp(-x)*poly(k1pp,7,z)/(poly(k1qq,7,z)*mw_sqrt(x));
    }
}

real besselK2(const real x) {
   return 2.0*besselK1(x)/x + besselK0(x);
}

