real aExp(const real k, const real R, const real Rd) {
    const real lim = R/Rd;
    const real kRd = k*Rd;
    if ((lim < 50) && (lim > 0.4) && (kRd < 50) && (kRd > 0.4)) {    /*Calculate from table using bilinear interpolation*/
        int lim_index = mw_floor(10*lim - 0.1);
        int kRd_index = mw_floor(10*kRd - 0.1);
        const real x1 = lim_index*0.1 + 0.01;
        const real x2 = (lim_index+1)*0.1 + 0.01;
        const real y1 = kRd_index*0.1 + 0.01;
        const real y2 = (kRd_index+1)*0.1 + 0.01;
        const real a11 = aExp_table[lim_index][kRd_index];
        const real a12 = aExp_table[lim_index][kRd_index+1];
        const real a21 = aExp_table[lim_index+1][kRd_index];
        const real a22 = aExp_table[lim_index+1][kRd_index+1];
        real val = 100.0*(a11*(x2 - lim)*(y2 - kRd) + a21*(lim - x1)*(y2 - kRd) + a12*(x2 - lim)*(kRd - y1) + a22*(lim - x1)*(kRd - y1));
        return mw_exp(val);
    } else {    /*Directly calculate*/
        const int n = 5;
        const real a = 0.0;
        const real b = lim;
        real integral = 0.0;
        const real weight[] = {5,8,5};
        const real point[] = {-0.774596669, 0 , 0.774596669};
        const real frac = 9.0;
        const real h = (b-a)/n;

        for (int i = 0; i < n; i++)
        {
        real piece = 0.0;
            for (int j = 0; j < 3; j++)
            {
                real x_val = h*point[j]/2 + a+(i+0.5)*h;
                real funcval = x_val*mw_exp(-x_val)*besselI0(kRd*x_val);
                piece = piece + h*weight[j]*funcval/frac/2.0;
            }
            integral  = integral + piece;
        }
        return integral;
    }
} 

real bExp(const real k, const real R, const real Rd) {
    const real lim = R/Rd;
    const real kRd = k*Rd;
    if ((lim < 50) && (lim > 0.04) && (kRd < 50) && (kRd > 0.04)) {    /*Calculate from table using bilinear interpolation*/
        int lim_index = mw_floor(10*lim - 0.1);
        int kRd_index = mw_floor(10*kRd - 0.1);
        const real x1 = lim_index*0.1 + 0.01;
        const real x2 = (lim_index+1)*0.1 + 0.01;
        const real y1 = kRd_index*0.1 + 0.01;
        const real y2 = (kRd_index+1)*0.1 + 0.01;
        const real a11 = bExp_table[lim_index][kRd_index];
        const real a12 = bExp_table[lim_index][kRd_index+1];
        const real a21 = bExp_table[lim_index+1][kRd_index];
        const real a22 = bExp_table[lim_index+1][kRd_index+1];
        real val = 100.0*(a11*(x2 - lim)*(y2 - kRd) + a21*(lim - x1)*(y2 - kRd) + a12*(x2 - lim)*(kRd - y1) + a22*(lim - x1)*(kRd - y1));
        return mw_exp(val);
    } else {    /*Directly calculate*/
        const int n = 8;
        const real a = lim;
        const real b = 20.0*lim;
        real integral = 0.0;
        const real weight[] = {5,8,5};
        const real point[] = {-0.774596669, 0 , 0.774596669};
        const real frac = 9.0;
        const real h = (b-a)/n;

        for (int i = 0; i < n; i++)
        {
            real piece = 0.0;
            for (int j = 0; j < 3; j++)
            {
                real x_val = h*point[j]/2 + a+(i+0.5)*h;
                real funcval = x_val*mw_exp(-x_val)*besselK0(kRd*x_val);
                piece = piece + h*weight[j]*funcval/frac/2.0;
            }
            integral  = integral + piece;
        }
        return integral;
    }
}



